package cc0.timecircles.naPHVO
import android.content.Context
import android.net.Uri
import cc0.timecircles.naPHVO.ephem.KernelInstaller
import java.io.BufferedInputStream
import java.io.BufferedOutputStream
import java.io.ByteArrayOutputStream
import java.io.File
import java.io.FileOutputStream
import java.security.MessageDigest
import java.util.Properties
import java.util.zip.ZipEntry
import java.util.zip.ZipInputStream
import java.util.zip.ZipOutputStream
import org.json.JSONArray
import org.json.JSONObject
private const val DATA_BACKUP_VERSION="DataBackup_v20261105T155723Z"
object DataBackup {
private fun digest(file:File):String { val md=MessageDigest.getInstance("SHA-256");file.inputStream().use { input -> val buf=ByteArray(262144);while(true) { val n=input.read(buf);if(n<0) break;md.update(buf,0,n) } };return md.digest().joinToString("") { "%02x".format(it.toInt() and 255) } }
fun export(context:Context,uri:Uri):String { val prefs=context.getSharedPreferences("time_circles_prefs",0);val gps=context.getSharedPreferences("time_circles_gps",0);val info=if(KernelInstaller.isInstalled(context)) KernelInstaller.installedInfo(context) else null;val state=JSONObject().put("format",1).put("locations",prefs.getString("locations_json","[]")?:"[]").put("anchors",prefs.getString("anchor_cache_json","{}")?:"{}").put("current",prefs.getBoolean("current_location_selected",true)).put("selected",prefs.getString("selected_location_key","")?:"").put("gps_lat",gps.getString("latitude","")?:"").put("gps_lon",gps.getString("longitude","")?:"").put("gps_time",gps.getLong("timestamp",0L));if(info!=null) state.put("spk",JSONObject().put("name",info.name).put("bytes",info.bytes).put("sha256",info.sha256).put("source","backup restore").put("installedAt",info.installedAt));val output=context.contentResolver.openOutputStream(uri,"w")?:error("Cannot write selected backup file");ZipOutputStream(BufferedOutputStream(output)).use { zip -> zip.putNextEntry(ZipEntry("state.json"));zip.write(state.toString().toByteArray(Charsets.UTF_8));zip.closeEntry();if(info!=null) { zip.putNextEntry(ZipEntry("kernel.bsp"));info.file.inputStream().use { it.copyTo(zip,262144) };zip.closeEntry() } };return if(info==null) "Locations backed up (no SPK installed)" else "Locations and ${info.name} backed up" }
fun restore(context:Context,uri:Uri):String { val dir=KernelInstaller.installedKernelDir(context);dir.mkdirs();val staged=File.createTempFile(".backup-import-",".bsp",dir);var state:JSONObject?=null;var kernelSize=0L;var hasKernel=false;val buffer=ByteArray(262144);try { val input=context.contentResolver.openInputStream(uri)?:error("Cannot read selected backup file");ZipInputStream(BufferedInputStream(input)).use { zip -> while(true) { val entry=zip.nextEntry?:break;when(entry.name) { "state.json" -> { val out=ByteArrayOutputStream();while(true) { val n=zip.read(buffer);if(n<0) break;if(out.size()+n>4194304) error("Backup metadata too large");out.write(buffer,0,n) };state=JSONObject(out.toString("UTF-8")) };"kernel.bsp" -> { if(hasKernel) error("Duplicate kernel");hasKernel=true;FileOutputStream(staged).use { output -> while(true) { val n=zip.read(buffer);if(n<0) break;kernelSize+=n;if(kernelSize>160000000L) error("Backup kernel too large");output.write(buffer,0,n) };output.fd.sync() } };else -> error("Unexpected backup entry: ${entry.name}") };zip.closeEntry() } };val data=state?:error("Backup has no state.json");if(data.optInt("format",0)!=1) error("Unsupported backup format");val locations=data.getString("locations");val anchors=data.getString("anchors");JSONArray(locations);JSONObject(anchors);val metadata=data.optJSONObject("spk");if(hasKernel) { val expected=metadata?:error("Kernel metadata missing");val bytes=expected.getLong("bytes");val hash=expected.getString("sha256");if(bytes!=kernelSize || !hash.matches(Regex("[a-fA-F0-9]{64}")) || !digest(staged).equals(hash,true)) error("Backup kernel failed SHA-256 integrity check");staged.inputStream().use { val header=ByteArray(7);if(it.read(header)!=7||String(header,Charsets.US_ASCII)!="DAF/SPK") error("Backup kernel is not an SPK") };val active=File(dir,"active.bsp");val record=File(dir,"active.properties");val prior=File(dir,".before-backup.bsp");val priorRecord=File(dir,".before-backup.properties");val nextRecord=File(dir,".backup-active.properties");prior.delete();priorRecord.delete();if(active.exists()&&!active.renameTo(prior)) error("Cannot preserve existing SPK");if(record.exists()&&!record.renameTo(priorRecord)) { if(prior.exists()) prior.renameTo(active);error("Cannot preserve existing SPK metadata") };try { if(!staged.renameTo(active)) error("Cannot install backup SPK");Properties().apply { setProperty("name",expected.getString("name"));setProperty("bytes",bytes.toString());setProperty("sha256",hash.lowercase());setProperty("source","backup restore");setProperty("installedAt",expected.optString("installedAt","unknown")) }.let { FileOutputStream(nextRecord).use { output -> it.store(output,null);output.fd.sync() } };if(!nextRecord.renameTo(record)) error("Cannot install backup metadata") } catch(e:Exception) { active.delete();record.delete();if(prior.exists()) prior.renameTo(active);if(priorRecord.exists()) priorRecord.renameTo(record);throw e } finally { nextRecord.delete() };prior.delete();priorRecord.delete() } else if(metadata!=null) error("Backup lists SPK but has no kernel file");context.getSharedPreferences("time_circles_prefs",0).edit().putString("locations_json",locations).putString("anchor_cache_json",anchors).putBoolean("current_location_selected",data.getBoolean("current")).putString("selected_location_key",data.optString("selected","")).commit();context.getSharedPreferences("time_circles_gps",0).edit().putString("latitude",data.optString("gps_lat","")).putString("longitude",data.optString("gps_lon","")).putLong("timestamp",data.optLong("gps_time",0L)).commit();return if(hasKernel) "Locations and SPK restored" else "Locations restored (existing SPK preserved)" } finally { staged.delete() } }
}
